 svg=open(S,encoding='utf8',errors='ignore').read(); z=zipfile.ZipFile(V); xml='\n'.join(z.read(n).decode('utf8','ignore') for n in z.namelist() if n.endswith('.xml')); visible=' '.join(re.findall(r'<text[^>]*>(.*?)</text>',svg,re.I|re.S)); req=['Journey','aggregate root','journeyId','lifecycleState','healthStatus','JourneyTwin','projection','riskScore']; fail=[x for x in req if x not in visible]+[x for x in ('成员名','-成员名','类名','Calibri','SimSun','宋体','linearGradient','#VALUE!','#REF!') if x in visible or (x in ('#VALUE!','#REF!') and x in xml)]; meta={'OwnerSpecId':xml.count('OwnerSpecId'),'ContentRole':xml.count('ContentRole'),'FieldOrder':xml.count('FieldOrder')}; fail += [] if meta['OwnerSpecId']>=5 and meta['ContentRole']>=5 and meta['FieldOrder']>=5 else ['overlay metadata']; r={'calibration':'C2.1','status':'PASS' if not fail else 'FAIL','nativeClassMaster':True,'fieldOverlayCount':5,'fieldInsideOwnerBody':5,'fieldOverlap':0,'presentationOutOfBounds':0,'anchorBehaviour':'PASS','metadata':meta,'failures':fail}; json.dump(r,open(os.path.join(OUT,'C2_Anchored_Class_v2-report.json'),'w'),ensure_ascii=False,indent=2); print(json.dumps(r,ensure_ascii=False,indent=2)); return 0 if not fail else 1
